 const saveUtility=async(e:any)=>{e.preventDefault();const isTag=utility==='tag';const r=isTag?await library.createTag(utilityForm.name):await library.createTask({title:utilityForm.title,description:utilityForm.description,project_id:utilityForm.project_id||undefined,priority:utilityForm.priority,due_at:utilityForm.due_at||undefined});if(r.error)setError(r.error.message);else{await library.logActivity('created',isTag?'tag':'task',r.data?.id,isTag?utilityForm.name:utilityForm.title);setUtility(null);await load()}};
 const addProject=()=>{setEditing(null);setForm({title:'',content:'',github_url:'',vercel_url:'',local_path:'',category:'web',accent_color:'#0F766E',cover_url:'',status:'active'});setComposer('project')};
 const addItem=(type:ItemType)=>{setEditing(null);setForm({title:'',content:'',url:'',project_id:selectedProject?.id||''});setComposer(type)};
 const saveComposer=async(e:any)=>{e.preventDefault();const wasEditing=!!editing;let r:any;if(editing&&composer==='project')r=await library.updateProject(editing.id,{name:form.title,description:form.content,github_url:form.github_url||null,vercel_url:form.vercel_url||null,local_path:form.local_path||null,category:form.category||'web',accent_color:form.accent_color||'#0F766E',cover_url:form.cover_url||null,status:form.status||'active'});else if(editing&&composer!=='project')r=await library.updateItem(editing.id,composer==='link'?{title:form.title,url:form.url,project_id:form.project_id||null}:{title:form.title,content:form.content,project_id:form.project_id||null});else if(composer==='project')r=await library.createProject(form.title,form.content,{github_url:form.github_url,vercel_url:form.vercel_url,local_path:form.local_path});else if(composer)r=await library.createItem(composer==='link'?{type:composer,title:form.title,url:form.url,project_id:form.project_id||undefined}:{type:composer,title:form.title,content:form.content,project_id:form.project_id||undefined});if(r?.error)setError(r.error.message);else{await library.logActivity(wasEditing?'updated':'created',composer==='project'?'project':String(composer),r?.data?.id||editing?.id,form.title);setComposer(null);setEditing(null);await load()}};
 const toggleFavorite=async(x:any)=>{await library.updateItem(x.id,{is_favorite:!x.is_favorite});await library.logActivity(x.is_favorite?'unfavorited':'favorited',x.type,x.id,x.title);load()};
 const toggleProjectFavorite=async(p:any,e?:any)=>{e?.stopPropagation?.();await library.updateProject(p.id,{is_favorite:!p.is_favorite});await library.logActivity(p.is_favorite?'unfavorited':'favorited','project',p.id,p.name);load()};
 const openFile=async(x:any)=>{if(!x.storage_path)return;const{data,error}=await supabase.storage.from('library').createSignedUrl(x.storage_path,300);if(error)setError(error.message);else{library.logActivity('opened','file',x.id,x.title);window.open(data.signedUrl,'_blank')}};
 const upload=async(e:any)=>{const file=e.target.files?.[0];if(!file)return;try{const r=await library.upload(file,selectedProject?.id);if(r.error)setError(r.error.message);else{await library.logActivity('uploaded','file',r.data?.id,file.name,{project_id:selectedProject?.id||null});await load()}}catch(x:any){setError(x.message)}e.target.value=''};
 const showVersions=async(x:any)=>{const r=await library.versions(x.id);if(r.error)setError(r.error.message);else{setVersions(r.data||[]);setVersionItem(x)}};
 const restoreVersion=async(v:any)=>{if(!versionItem)return;const r=await library.restoreVersion(versionItem,v);if(r.error)setError(r.error.message);else{await library.logActivity('restored_version','file',versionItem.id,versionItem.title,{from_version:v.version});setMsg('تم استرجاع الإصدار كنسخة حالية جديدة');setVersionItem(null);await load()}};
 const quickTask=()=>{if(!selectedProject)return;setUtilityForm({title:'',description:'',project_id:selectedProject.id,priority:'medium',due_at:''});setUtility('task')};
 const cycleTask=async(t:any)=>{const status=t.status==='todo'?'doing':t.status==='doing'?'done':'todo';await library.updateTask(t.id,{status});await library.logActivity(status==='done'?'completed':'updated','task',t.id,t.title,{status});load()};
 const replaceFile=async(e:any)=>{const file=e.target.files?.[0];if(!file||!replaceTarget)return;try{const r=await library.replaceFile(replaceTarget,file);if(r.error)setError(r.error.message);else{await library.logActivity('updated','file',replaceTarget.id,replaceTarget.title,{version:r.data?.version});await load()}}catch(x:any){setError(x.message)}setReplaceTarget(null);e.target.value=''};
 const runGlobalSearch=async(q:string)=>{setCommandQuery(q);if(!q.trim()){setCommandResults({projects:[],items:[],tasks:[],tags:[]});return}setCommandResults(await library.globalSearch(q))};
 const search=(e:any)=>{setCommandOpen(true);runGlobalSearch(e.target.value)};
 const openProject=async(p:any)=>{setHubTab('overview');setSelectedProject(p);const tg=await library.projectTags(p.id);setProjectTagIds((tg.data||[]).map((x:any)=>x.tag_id));library.touchProject(p.id);library.logActivity('opened','project',p.id,p.name)};
 const toggleProjectTag=async(tagId:string)=>{if(!selectedProject)return;const has=projectTagIds.includes(tagId);if(has){await library.untagProject(selectedProject.id,tagId);setProjectTagIds(x=>x.filter(id=>id!==tagId))}else{await library.tagProject(selectedProject.id,tagId);setProjectTagIds(x=>[...x,tagId])}};
 const openItemTags=async(item:any)=>{setItemTagTarget(item);const r=await library.itemTags(item.id);setItemTagIds((r.data||[]).map((x:any)=>x.tag_id))};
 const toggleItemTag=async(tagId:string)=>{if(!itemTagTarget)return;const has=itemTagIds.includes(tagId);if(has){await library.untagItem(itemTagTarget.id,tagId);setItemTagIds(x=>x.filter(id=>id!==tagId))}else{await library.tagItem(itemTagTarget.id,tagId);setItemTagIds(x=>[...x,tagId])}};
 const syncGithub=async()=>{setSyncing(true);setError('');const r=await library.syncGithub('MostafaAhmed71',githubToken||undefined);if(r.error)setError(r.error.message);else{await library.logActivity('synced','github',undefined,'GitHub',{count:r.data?.count||0});setMsg(`تمت مزامنة ${r.data?.count||0} مستودع من GitHub`);setSyncOpen(false);await load()}setSyncing(false)};
